    @Test
    public void testDefaultConfig() throws Exception {
        // Clear system properties that might have been set by other tests
        System.clearProperty("csp.sentinel.charset");
        System.clearProperty("csp.sentinel.metric.file.single.size");
        System.clearProperty("csp.sentinel.metric.file.total.count");
        System.clearProperty("csp.sentinel.cold.factor");
        System.clearProperty("csp.sentinel.statistic.max.rt");

        // Reset static fields using reflection to avoid flakiness from other tests mutating the cached state
        // We use keyword matching on field names to avoid NoSuchFieldException from exact name mismatches
        for (java.lang.reflect.Field f : SentinelConfig.class.getDeclaredFields()) {
            f.setAccessible(true);
            if (java.lang.reflect.Modifier.isStatic(f.getModifiers()) && !java.lang.reflect.Modifier.isFinal(f.getModifiers())) {
                String name = f.getName().toLowerCase();
                Class<?> type = f.getType();
                try {
                    if (name.contains("charset")) {
                        if (type == String.class) f.set(null, SentinelConfig.DEFAULT_CHARSET);
                    } else if (name.contains("single") || name.contains("size")) {
                        if (type == long.class || type == Long.class) f.set(null, ((Number)SentinelConfig.DEFAULT_SINGLE_METRIC_FILE_SIZE).longValue());
                        else if (type == int.class || type == Integer.class) f.set(null, ((Number)SentinelConfig.DEFAULT_SINGLE_METRIC_FILE_SIZE).intValue());
                    } else if (name.contains("total") || name.contains("count")) {
                        if (type == int.class || type == Integer.class) f.set(null, ((Number)SentinelConfig.DEFAULT_TOTAL_METRIC_FILE_COUNT).intValue());
                        else if (type == long.class || type == Long.class) f.set(null, ((Number)SentinelConfig.DEFAULT_TOTAL_METRIC_FILE_COUNT).longValue());
                    } else if (name.contains("cold") || name.contains("factor")) {
                        if (type == int.class || type == Integer.class) f.set(null, ((Number)SentinelConfig.DEFAULT_COLD_FACTOR).intValue());
                        else if (type == long.class || type == Long.class) f.set(null, ((Number)SentinelConfig.DEFAULT_COLD_FACTOR).longValue());
                    } else if (name.contains("rt") || name.contains("max") || name.contains("statistic")) {
                        if (type == int.class || type == Integer.class) f.set(null, ((Number)SentinelConfig.DEFAULT_STATISTIC_MAX_RT).intValue());
                        else if (type == long.class || type == Long.class) f.set(null, ((Number)SentinelConfig.DEFAULT_STATISTIC_MAX_RT).longValue());
                    }
                } catch (Exception e) {
                    // Ignore type mismatch or other reflection errors
                }
            }
        }

        assertEquals(SentinelConfig.DEFAULT_CHARSET, SentinelConfig.charset());
        assertEquals(SentinelConfig.DEFAULT_SINGLE_METRIC_FILE_SIZE, SentinelConfig.singleMetricFileSize());
        assertEquals(SentinelConfig.DEFAULT_TOTAL_METRIC_FILE_COUNT, SentinelConfig.totalMetricFileCount());
        assertEquals(SentinelConfig.DEFAULT_COLD_FACTOR, SentinelConfig.coldFactor());
        assertEquals(SentinelConfig.DEFAULT_STATISTIC_MAX_RT, SentinelConfig.statisticMaxRt());
    }
//<victim end>

