        assertEquals(sortFields(expected2), sortFields(actual2));

        String expected3 = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]";
        String actual3 = this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class);
        assertEquals(sortFields(expected3), sortFields(actual3));

        String expected4 = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]";
        String actual4 = this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class);
        assertEquals(sortFields(expected4), sortFields(actual4));
    }

    private String sortFields(String str) {
        int start = str.indexOf('[');
        int end = str.lastIndexOf(']');
        if (start < 0 || end < 0) return str;
        String[] fields = str.substring(start + 1, end).split(",");
        java.util.Arrays.sort(fields);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < fields.length; i++) {
            if (i > 0) sb.append(",");
            sb.append(fields[i]);
        }
        return str.substring(0, start + 1) + sb.toString() + str.substring(end);
    }
//<fix end>

