    @Test
    public void testReflectionHashCodeExcludeFields() throws Exception {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);

        int expectedAll = 17;
        int expectedExcludeTwo = 17;
        int expectedExcludeThree = 17;
        int expectedExcludeTwoThree = 17;

        // Compute expected hash codes dynamically based on the actual field order
        // to avoid flakiness caused by non-deterministic reflection field order.
        for (Field f : x.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            int val = f.get(x).hashCode();
            expectedAll = expectedAll * 37 + val;
            if (!f.getName().equals("two")) {
                expectedExcludeTwo = expectedExcludeTwo * 37 + val;
            }
            if (!f.getName().equals("three")) {
                expectedExcludeThree = expectedExcludeThree * 37 + val;
            }
            if (!f.getName().equals("two") && !f.getName().equals("three")) {
                expectedExcludeTwoThree = expectedExcludeTwoThree * 37 + val;
            }
        }

        assertEquals(expectedAll, HashCodeBuilder.reflectionHashCode(x));
        assertEquals(expectedAll, HashCodeBuilder.reflectionHashCode(x, (String[]) null));
        assertEquals(expectedAll, HashCodeBuilder.reflectionHashCode(x));
        assertEquals(expectedAll, HashCodeBuilder.reflectionHashCode(x, "xxx"));

        assertEquals(expectedExcludeTwo, HashCodeBuilder.reflectionHashCode(x, "two"));
        assertEquals(expectedExcludeThree, HashCodeBuilder.reflectionHashCode(x, "three"));

        assertEquals(expectedExcludeTwoThree, HashCodeBuilder.reflectionHashCode(x, "two", "three"));

        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three"));
        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx"));
    }
