    @Test
    public void testInheritedReflectionStatics() throws Exception {
        // Reset static variables to their default values to prevent flakiness from other tests
        setFinalStatic(SimpleReflectionStaticFieldsFixture.class, "staticString", "staticString");
        setFinalStatic(SimpleReflectionStaticFieldsFixture.class, "staticInt", 12345);
        setFinalStatic(InheritedReflectionStaticFieldsFixture.class, "staticString2", "staticString2");
        setFinalStatic(InheritedReflectionStaticFieldsFixture.class, "staticInt2", 67890);

        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        String expected1 = this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]";
        String actual1 = ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class);
        assertEquals(normalizeReflectionString(expected1), normalizeReflectionString(actual1));

        String expected2 = this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]";
        String actual2 = ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeReflectionString(expected2), normalizeReflectionString(actual2));

        String expected3 = this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]";
        String actual3 = this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeReflectionString(expected3), normalizeReflectionString(actual3));

        String expected4 = this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]";
        String actual4 = this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeReflectionString(expected4), normalizeReflectionString(actual4));
    }

    private String normalizeReflectionString(String s) {
        int start = s.indexOf('[');
        int end = s.lastIndexOf(']');
        if (start == -1 || end == -1) return s;
        String prefix = s.substring(0, start + 1);
        String suffix = s.substring(end);
        String fields = s.substring(start + 1, end);
        String[] parts = fields.split(",");
        java.util.Arrays.sort(parts);
        return prefix + String.join(",", parts) + suffix;
    }

    private void setFinalStatic(Class<?> clazz, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = clazz.getDeclaredField(fieldName);
        field.setAccessible(true);
        java.lang.reflect.Field modifiersField = java.lang.reflect.Field.class.getDeclaredField("modifiers");
        modifiersField.setAccessible(true);
        modifiersField.setInt(field, field.getModifiers() & ~java.lang.reflect.Modifier.FINAL);
        field.set(null, value);
    }
