        when(healthStateAggregator.healthStateView(barView.getName())).thenReturn(Optional.of(barView));
        when(healthStateAggregator.healthStateView(bazView.getName())).thenReturn(Optional.of(bazView));
        when(healthStatusChecker.isHealthy(isNull())).thenReturn(true);
        final HealthResponse response = jsonHealthResponseProvider.healthResponse(queryParams);

        // then
        assertThat(response.isHealthy()).isTrue();
        assertThat(response.getContentType()).isEqualTo(MediaType.APPLICATION_JSON);

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        com.fasterxml.jackson.databind.JsonNode actualNode = mapper.readTree(response.getMessage());
        com.fasterxml.jackson.databind.JsonNode expectedNode = mapper.readTree(fixture("/json/multiple-healthy-responses.json"));

        java.util.function.Function<com.fasterxml.jackson.databind.JsonNode, String> canonicalize = new java.util.function.Function<com.fasterxml.jackson.databind.JsonNode, String>() {
            @Override
            public String apply(com.fasterxml.jackson.databind.JsonNode node) {
                if (node.isArray()) {
                    java.util.List<String> list = new java.util.ArrayList<>();
                    for (com.fasterxml.jackson.databind.JsonNode n : node) {
                        list.add(apply(n));
                    }
                    java.util.Collections.sort(list);
                    return "[" + String.join(",", list) + "]";
                } else if (node.isObject()) {
                    java.util.List<String> fields = new java.util.ArrayList<>();
                    java.util.Iterator<java.util.Map.Entry<String, com.fasterxml.jackson.databind.JsonNode>> it = node.fields();
                    while (it.hasNext()) {
                        java.util.Map.Entry<String, com.fasterxml.jackson.databind.JsonNode> entry = it.next();
                        fields.add("\"" + entry.getKey() + "\":" + apply(entry.getValue()));
                    }
                    java.util.Collections.sort(fields);
                    return "{" + String.join(",", fields) + "}";
                } else {
                    return node.toString();
                }
            }
        };

        assertThat(canonicalize.apply(actualNode)).isEqualTo(canonicalize.apply(expectedNode));
    }
