  public void testAvroDoc() throws Exception {
    String expectedJson = "{\"type\":\"record\",\"name\":\"DocTest\",\"namespace\":\"org.apache.avro.reflect.TestReflect\","
        + "\"doc\":\"DocTest class docs\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"doc\":\"Some Documentation\"},"
        + "{\"name\":\"enums\",\"type\":{\"type\":\"enum\",\"name\":\"DocTestEnum\","
        + "\"symbols\":[\"ENUM_1\",\"ENUM_2\"]},\"doc\":\"Some other Documentation\"},"
        + "{\"name\":\"defaultTest\",\"type\":{\"type\":\"record\",\"name\":\"DefaultTest\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"default\":1}]},\"doc\":\"And again\"}]}";

    String actualJson = ReflectData.get().getSchema(DocTest.class).toString();

    com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
    Map<String, Object> expectedMap = mapper.readValue(expectedJson, Map.class);
    Map<String, Object> actualMap = mapper.readValue(actualJson, Map.class);

    java.util.function.Consumer<Map<String, Object>> sortFields = new java.util.function.Consumer<Map<String, Object>>() {
      @Override
      @SuppressWarnings("unchecked")
      public void accept(Map<String, Object> map) {
        if (map.containsKey("fields")) {
          Object fieldsObj = map.get("fields");
          if (fieldsObj instanceof List) {
            List<Object> fields = (List<Object>) fieldsObj;
            List<Map<String, Object>> sortedFields = new ArrayList<>();
            for (Object f : fields) {
              if (f instanceof Map) {
                Map<String, Object> fieldMap = (Map<String, Object>) f;
                this.accept(fieldMap);
                if (fieldMap.containsKey("type") && fieldMap.get("type") instanceof Map) {
                  this.accept((Map<String, Object>) fieldMap.get("type"));
                }
                sortedFields.add(fieldMap);
              }
            }
            sortedFields.sort(Comparator.comparing(m -> (String) m.get("name")));
            map.put("fields", sortedFields);
          }
        }
      }
    };

    sortFields.accept(expectedMap);
    sortFields.accept(actualMap);

    assertEquals(expectedMap, actualMap);
  }
