  @Test
  public void testAvroDoc() throws Exception {
    String expectedJson = "{\"type\":\"record\",\"name\":\"DocTest\",\"namespace\":\"org.apache.avro.reflect.TestReflect\","
        + "\"doc\":\"DocTest class docs\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"doc\":\"Some Documentation\"},"
        + "{\"name\":\"enums\",\"type\":{\"type\":\"enum\",\"name\":\"DocTestEnum\","
        + "\"symbols\":[\"ENUM_1\",\"ENUM_2\"]},\"doc\":\"Some other Documentation\"},"
        + "{\"name\":\"defaultTest\",\"type\":{\"type\":\"record\",\"name\":\"DefaultTest\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"default\":1}]},\"doc\":\"And again\"}]}";

    Schema actualSchema = ReflectData.get().getSchema(DocTest.class);
    String actualJson = actualSchema.toString();

    com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
    com.fasterxml.jackson.databind.JsonNode expectedTree = mapper.readTree(expectedJson);
    com.fasterxml.jackson.databind.JsonNode actualTree = mapper.readTree(actualJson);

    java.util.function.Consumer<com.fasterxml.jackson.databind.JsonNode> sortFields = new java.util.function.Consumer<com.fasterxml.jackson.databind.JsonNode>() {
      public void accept(com.fasterxml.jackson.databind.JsonNode node) {
        if (node.isObject()) {
          com.fasterxml.jackson.databind.ObjectNode obj = (com.fasterxml.jackson.databind.ObjectNode) node;
          if (obj.has("fields") && obj.get("fields").isArray()) {
            com.fasterxml.jackson.databind.ArrayNode arr = (com.fasterxml.jackson.databind.ArrayNode) obj.get("fields");
            java.util.List<com.fasterxml.jackson.databind.JsonNode> list = new java.util.ArrayList<>();
            arr.forEach(list::add);
            list.sort(java.util.Comparator.comparing(n -> n.get("name").asText()));
            arr.removeAll();
            list.forEach(arr::add);
          }
          java.util.Iterator<com.fasterxml.jackson.databind.JsonNode> elements = obj.elements();
          while (elements.hasNext()) {
            this.accept(elements.next());
          }
        } else if (node.isArray()) {
          for (com.fasterxml.jackson.databind.JsonNode child : node) {
            this.accept(child);
          }
        }
      }
    };

    sortFields.accept(expectedTree);
    sortFields.accept(actualTree);

    assertEquals(expectedTree, actualTree);
  }
