  public void testAvroDoc() throws Exception {
    String expectedJson = "{\"type\":\"record\",\"name\":\"DocTest\",\"namespace\":\"org.apache.avro.reflect.TestReflect\","
        + "\"doc\":\"DocTest class docs\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"doc\":\"Some Documentation\"},"
        + "{\"name\":\"enums\",\"type\":{\"type\":\"enum\",\"name\":\"DocTestEnum\","
        + "\"symbols\":[\"ENUM_1\",\"ENUM_2\"]},\"doc\":\"Some other Documentation\"},"
        + "{\"name\":\"defaultTest\",\"type\":{\"type\":\"record\",\"name\":\"DefaultTest\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"default\":1}]},\"doc\":\"And again\"}]}";

    String actualJson = ReflectData.get().getSchema(DocTest.class).toString();

    com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
    Object expectedObj = mapper.convertValue(mapper.readTree(expectedJson), Object.class);
    Object actualObj = mapper.convertValue(mapper.readTree(actualJson), Object.class);

    java.util.function.Consumer<Object> sort = new java.util.function.Consumer<Object>() {
      @SuppressWarnings("unchecked")
      public void accept(Object obj) {
        if (obj instanceof java.util.Map) {
          java.util.Map<String, Object> map = (java.util.Map<String, Object>) obj;
          if (map.containsKey("fields")) {
            Object fields = map.get("fields");
            if (fields instanceof java.util.List) {
              java.util.List<java.util.Map<String, Object>> list = (java.util.List<java.util.Map<String, Object>>) fields;
              list.sort(java.util.Comparator.comparing(m -> (String) m.get("name")));
            }
          }
          for (Object val : map.values()) {
            this.accept(val);
          }
        } else if (obj instanceof java.util.List) {
          for (Object val : (java.util.List<?>) obj) {
            this.accept(val);
          }
        }
      }
    };

    sort.accept(expectedObj);
    sort.accept(actualObj);

    assertEquals(expectedObj, actualObj);
  }
