        possibleAll.add(((17 * 37 + v2) * 37 + v3) * 37 + v1);
        possibleAll.add(((17 * 37 + v3) * 37 + v1) * 37 + v2);
        possibleAll.add(((17 * 37 + v3) * 37 + v2) * 37 + v1);

        java.util.Set<Integer> possibleExcludeTwo = new java.util.HashSet<>();
        possibleExcludeTwo.add((17 * 37 + v1) * 37 + v3);
        possibleExcludeTwo.add((17 * 37 + v3) * 37 + v1);

        java.util.Set<Integer> possibleExcludeThree = new java.util.HashSet<>();
        possibleExcludeThree.add((17 * 37 + v1) * 37 + v2);
        possibleExcludeThree.add((17 * 37 + v2) * 37 + v1);

        org.junit.jupiter.api.Assertions.assertTrue(possibleAll.contains(HashCodeBuilder.reflectionHashCode(x)));
        org.junit.jupiter.api.Assertions.assertTrue(possibleAll.contains(HashCodeBuilder.reflectionHashCode(x, (String[]) null)));
