    @Test
    public void testSensitiveValueEncryptDecrypt() throws Exception {
        final String originalValue = "OriginalSensitiveValue";

        SensitiveValue value = (SensitiveValue) ValueFactory.create(originalValue, true);

        java.util.function.Consumer<SensitiveValue> verifyEnc = (v) -> {
            try {
                String encStr = null;
                // Attempt to find the encrypted string via getters
                for (java.lang.reflect.Method m : v.getClass().getMethods()) {
                    if (m.getParameterCount() == 0 && m.getReturnType() == String.class) {
                        try {
                            String res = (String) m.invoke(v);
                            if (res != null && res.contains("{Encrypted}")) {
                                encStr = res;
                                break;
                            }
                        } catch (Exception e) {}
                    }
                }
                // Fallback to fields if not found
                if (encStr == null) {
                    for (java.lang.reflect.Field f : v.getClass().getDeclaredFields()) {
                        if (f.getType() == String.class) {
                            try {
                                f.setAccessible(true);
                                String res = (String) f.get(v);
                                if (res != null && res.contains("{Encrypted}")) {
                                    encStr = res;
                                    break;
                                }
                            } catch (Exception e) {}
                        }
                    }
                }
                // Final fallback to toString
                if (encStr == null) encStr = v.toString();

                org.junit.Assert.assertTrue("Should contain {Encrypted}", encStr.contains("{Encrypted}"));
                String b64 = encStr.substring(encStr.indexOf("{Encrypted}") + "{Encrypted}".length()).trim();

                // Use MimeDecoder to be resilient against any line-break formatting differences in Base64
                byte[] bytes = java.util.Base64.getMimeDecoder().decode(b64);
                java.io.ObjectInputStream ois = new java.io.ObjectInputStream(new java.io.ByteArrayInputStream(bytes));
                Object deserialized = ois.readObject();

                // Compare the deserialized data format rather than the strict string representation
                if (deserialized instanceof char[]) {
                    org.junit.Assert.assertEquals(originalValue, new String((char[]) deserialized));
                } else if (deserialized instanceof byte[]) {
                    org.junit.Assert.assertEquals(originalValue, new String((byte[]) deserialized));
                } else {
                    org.junit.Assert.assertEquals(originalValue, deserialized.toString());
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        };

        verifyEnc.accept(value);

        value.encrypt();
        verifyEnc.accept(value);

        value.decrypt();
        verifyDecrypted(value, originalValue);

        value.decrypt();
        verifyDecrypted(value, originalValue);

        value.encrypt();
        verifyEnc.accept(value);

        value.encrypt();
        verifyEnc.accept(value);
    }
//<victim end>

