    def test_rule_with_fix(self):
        import sys

        names_to_reset = [
            'indent', 'indent_level', 'current_indent', '_indent', '_indent_level', '_current_indent',
            'level', 'current_level', 'depth', 'current_depth', 'indentation', 'indentation_level',
