                        except Exception:
                            continue
                        if not isinstance(instance, type) and not callable(instance) and not isinstance(instance, (int, str, float, bool, list, dict, tuple, set)):
                            for sub_attr in names_to_reset:
                                if hasattr(instance, sub_attr):
