    @Test
    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        // Use reflection to enforce deterministic iteration order on internal collections
        // to prevent Implementation-Dependent (ID) flakiness from unordered APIs like HashSet
        java.util.function.Consumer<Object> sortAnnotations = (obj) -> {
            try {
                Class<?> clazz = obj.getClass();
                while (clazz != null) {
                    for (java.lang.reflect.Field field : clazz.getDeclaredFields()) {
                        if (java.util.Collection.class.isAssignableFrom(field.getType())) {
                            field.setAccessible(true);
                            java.util.Collection<?> col = (java.util.Collection<?>) field.get(obj);
                            if (col != null && !col.isEmpty() && col.iterator().next() instanceof Annotation) {
                                java.util.List<Annotation> list = new java.util.ArrayList<>((java.util.Collection<Annotation>) col);
                                list.sort(java.util.Comparator.comparing(Annotation::toString));
                                if (col instanceof java.util.Set) {
                                    field.set(obj, new java.util.LinkedHashSet<>(list));
                                } else {
                                    field.set(obj, list);
                                }
                            }
                        }
                    }
                    clazz = clazz.getSuperclass();
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        };

        sortAnnotations.accept(a);
        sortAnnotations.accept(b);

        Assert.assertEquals(a, b);
        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
