                Class<?> clazz = obj.getClass();
                while (clazz != null) {
                    for (java.lang.reflect.Field field : clazz.getDeclaredFields()) {
                        field.setAccessible(true);
                        Object val = field.get(obj);
                        if (val instanceof Annotation[]) {
                            Annotation[] arr = (Annotation[]) val;
                            if (arr.length > 1) {
                                java.util.Arrays.sort(arr, java.util.Comparator.comparing(Annotation::toString));
                            }
                        } else if (val instanceof java.util.List) {
                            java.util.List<Annotation> list = (java.util.List<Annotation>) val;
                            if (list.size() > 1 && list.get(0) instanceof Annotation) {
                                try {
