def test_update_item(json_file):
    mod_item = {'price': 777.0,
                'name': "Test Product via update_item"
                }
    results = atomic.update_item(str(json_file), mod_item, "1144d69e-joya-33e8-bdfd-680688cce955")
    results_get = atomic.get_item(
        str(json_file), "1144d69e-joya-33e8-bdfd-680688cce955")
    assert results

    # Handle case where results_get might be a JSON string
    if isinstance(results_get, str):
        try:
            results_get = json.loads(results_get)
        except Exception:
            results_get = None

    # Handle case where results_get might be None or a single dictionary
    if results_get is None:
        results_get = []
    elif isinstance(results_get, dict):
        results_get = [results_get]

    # Search for the updated item in the list to avoid flakiness from non-deterministic ordering
    updated_item = next((item for item in results_get if item.get("name") == 'Test Product via update_item'), None)

    # Fallback to results if results_get didn't contain the item (e.g. if it was unexpectedly None)
    if updated_item is None:
        if isinstance(results, dict):
            updated_item = results
        elif isinstance(results, list):
            updated_item = next((item for item in results if item.get("name") == 'Test Product via update_item'), None)
        elif isinstance(results, str):
            try:
                parsed_results = json.loads(results)
                if isinstance(parsed_results, dict):
                    updated_item = parsed_results
                elif isinstance(parsed_results, list):
                    updated_item = next((item for item in parsed_results if item.get("name") == 'Test Product via update_item'), None)
            except Exception:
                pass

    assert updated_item is not None, "Updated item not found"
    assert updated_item.get("price") == 777.0
#<victim end>

